// Command docgen renders docs/reference/*.md from the schema and code that
// already define holaclaw's config, CLI, API, check rules and events, so the
// docs can never disagree with the parser (ARCHITECTURE.md §7).
//
// Usage:
//
//	go run ./tools/docgen --out docs/reference
//
// Every generated file starts with the same "do not edit" header and is
// written deterministically: stable ordering, no timestamps, no absolute
// paths. `just docs` regenerates in place; `just docs-check` regenerates into
// a temporary directory and diffs against the committed one.
package main

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

// generatedHeader is the first line of every file this tool writes.
const generatedHeader = "<!-- Generated by tools/docgen. Do not edit. -->\n\n"

func main() {
	var out string
	cmd := &cobra.Command{
		Use:           "docgen [--out dir]",
		Short:         "render docs/reference from the schema and code",
		Args:          cobra.NoArgs,
		SilenceErrors: true,
		SilenceUsage:  true,
		RunE:          func(*cobra.Command, []string) error { return Generate(out) },
	}
	cmd.Flags().StringVar(&out, "out", "docs/reference", "output directory for the generated reference docs")
	cmd.SetFlagErrorFunc(func(c *cobra.Command, err error) error {
		fmt.Fprintf(os.Stderr, "docgen: %v\n%s", err, c.UsageString())
		os.Exit(2)
		return nil
	})
	if err := cmd.Execute(); err != nil {
		fmt.Fprintln(os.Stderr, "docgen:", err)
		os.Exit(1)
	}
}
